package com.siiiweb.comment.controller;import com.siiiweb.comment.entity.Comment;import com.siiiweb.comment.repository.CommentRepository;import org.springframework.web.bind.annotation.*;import java.util.*;@RestController public class CommentController{private final CommentRepository repo;public CommentController(CommentRepository r){repo=r;}@PostMapping("/api/comments") public Comment create(@RequestBody Comment c){c.status="PENDING";return repo.save(c);}@GetMapping("/api/admin/comments") public List<Comment> pending(){return repo.findByStatus("PENDING");}@PutMapping("/api/admin/comments/{id}/approve") public Comment approve(@PathVariable Long id,@RequestBody(required=false) Map<String,String> body){Comment c=repo.findById(id).orElseThrow();c.status="APPROVED";if(body!=null)c.reply=body.get("reply");return repo.save(c);}@DeleteMapping("/api/admin/comments/{id}") public void del(@PathVariable Long id){repo.deleteById(id);}}
